const inItem = $input.first().json || {};
const body = inItem.body || {};
const headers = inItem.headers || {};

const rand = () => Math.random().toString(36).slice(2, 8).toUpperCase();
const requestId = 'REQ-' + Date.now().toString(36).toUpperCase() + '-' + rand();
const correlationId = headers['x-correlation-id'] || ('COR-' + rand() + rand());
const idempotencyKey = headers['idempotency-key'] || headers['x-idempotency-key'] || ('IDK-' + rand() + rand());

const errors = [];
const isObj = (v) => v && typeof v === 'object' && !Array.isArray(v);

if (!body.propertyId || typeof body.propertyId !== 'string') errors.push('propertyId is required');
if (!body.passportId || typeof body.passportId !== 'string') errors.push('passportId is required');
if (!isObj(body.property)) errors.push('property object is required');

const p = isObj(body.property) ? body.property : {};
for (const f of ['title', 'address', 'region', 'country', 'type', 'owner', 'status']) {
  if (p[f] == null || p[f] === '') errors.push('property.' + f + ' is required');
}
if (p.area != null && (typeof p.area !== 'number' || p.area <= 0)) errors.push('property.area must be a positive number');
if (p.boundaryVertices != null && (typeof p.boundaryVertices !== 'number' || p.boundaryVertices < 3)) {
  errors.push('property.boundaryVertices must be >= 3');
}

const documents = Array.isArray(body.documents) ? body.documents : [];
const ALLOWED_EXT = ['pdf', 'jpg', 'jpeg', 'png'];
documents.forEach((d, i) => {
  if (!d || typeof d !== 'object') { errors.push('documents[' + i + '] is invalid'); return; }
  const name = String(d.name || '');
  const ext = name.includes('.') ? name.split('.').pop().toLowerCase() : '';
  if (ext && !ALLOWED_EXT.includes(ext)) errors.push('documents[' + i + '] has unsupported file type .' + ext);
});

const existingScores = isObj(body.existingScores) ? body.existingScores : {};

// UUID identifiers supplied by the caller for Supabase FK / NOT NULL columns.
const propertyUuid = body.propertyUuid || body.propertyUUID || (isObj(body.property) ? (body.property.uuid || body.property.id) : null) || null;
const userId = body.userId || body.userUuid || body.notificationUserId || null;

// Roles for audit + notification records. Automated verification acts as 'system';
// the notification recipient defaults to the property owner unless the caller specifies.
const actorRole = body.actorRole || 'system';
const recipientRole = body.recipientRole || body.role || 'owner';

if (errors.length) {
  return [{ json: {
    __error: true, __httpStatus: 400,
    __errorCode: 'VALIDATION_ERROR',
    __errorMessage: errors.join('; '),
    requestId, correlationId, idempotencyKey,
    __auditEvent: 'property_submission_rejected',
    propertyId: body.propertyId || null, passportId: body.passportId || null,
  } }];
}

// Normalized, validated payload flowing downstream.
return [{ json: {
  __error: false,
  requestId, correlationId, idempotencyKey,
  _headers: headers,
  propertyId: body.propertyId,
  passportId: body.passportId,
  propertyUuid,
  userId,
  actorRole,
  recipientRole,
  property: p,
  documents,
  existingScores,
  __auditEvent: 'property_submission',
} }];

const d = $input.first().json;
const p = d.property || {};
const docs = Array.isArray(d.documents) ? d.documents : [];
const ex = d.existingScores || {};
const clamp = (n) => Math.max(0, Math.min(100, Math.round(n)));
const getEnv = (k, def) => { try { const v = $env && $env[k]; return (v == null || v === '') ? def : v; } catch (e) { return def; } };

// ===== Stage 5: Document / OCR analysis =====
const REQUIRED_FIELDS = ['ownerName','plotNumber','surveyReference','area','issuedDate','issuingAuthority','bureauStampId','coordinates'];
const extracted = {
  ownerName: p.owner || null,
  plotNumber: p.plotNumber || (docs[0] && docs[0].plotNumber) || null,
  surveyReference: p.surveyReference || null,
  area: p.area || null,
  issuedDate: (docs[0] && docs[0].issuedDate) || null,
  issuingAuthority: (docs[0] && docs[0].issuingAuthority) || null,
  bureauStampId: (docs[0] && docs[0].bureauStampId) || null,
  coordinates: p.coordinates || (docs[0] && docs[0].coordinates) || null,
};
const missingFields = REQUIRED_FIELDS.filter(f => extracted[f] == null || extracted[f] === '');
const anomalies = { altered:false, mismatchedStamp:false, inconsistentFonts:false, duplicateDoc:false, invalidDates:false };
const seen = new Set();
for (const doc of docs) {
  const fp = (doc.fingerprint || doc.id || doc.name || '') + '';
  if (seen.has(fp)) anomalies.duplicateDoc = true; else seen.add(fp);
  if (doc.issuedDate && isNaN(Date.parse(doc.issuedDate))) anomalies.invalidDates = true;
  if (doc.mismatchedStamp === true) anomalies.mismatchedStamp = true;
  if (doc.altered === true) anomalies.altered = true;
  if (doc.inconsistentFonts === true) anomalies.inconsistentFonts = true;
}
const docsPresentAndVerified = docs.length > 0 && docs.every(x => x.verified === true);
let ocrConfidence = docsPresentAndVerified ? 96 : (docs.length ? 70 : 40);
ocrConfidence -= missingFields.length * 6;
if (anomalies.duplicateDoc || anomalies.invalidDates) ocrConfidence -= 25;
ocrConfidence = clamp(ocrConfidence);
const anomalyDetected = Object.values(anomalies).some(Boolean);
const documentsVerified = docsPresentAndVerified && missingFields.length === 0 && !anomalyDetected;

// ===== Stage 6: Fraud detection =====
const fraudSignals = [];
if (anomalies.duplicateDoc) fraudSignals.push({ type: 'duplicate_document_fingerprint', severity: 'high' });
if (anomalies.mismatchedStamp) fraudSignals.push({ type: 'forged_stamp', severity: 'critical' });
const docOwner = docs.map(x => x && x.owner).find(o => o != null && o !== '');
if (docOwner && p.owner && String(docOwner).toLowerCase() !== String(p.owner).toLowerCase())
  fraudSignals.push({ type: 'owner_identity_mismatch', severity: 'critical' });
let fraudScore = 12;
if (p.status && p.status !== 'verified') fraudScore += 15;
fraudSignals.forEach(s => { fraudScore += s.severity === 'critical' ? 40 : s.severity === 'high' ? 20 : 8; });
fraudScore = clamp(fraudScore);
const fraudBand = fraudScore >= 70 ? 'Critical' : fraudScore >= 45 ? 'Elevated' : fraudScore >= 25 ? 'Watch' : 'Clear';
const criticalFraudSignal = fraudSignals.some(s => s.severity === 'critical');
const fraudRecommendedAction = fraudBand === 'Critical' ? 'reject' : fraudBand === 'Elevated' ? 'manual_review' : fraudBand === 'Watch' ? 'monitor' : 'proceed';

// ===== Stage 7: Boundary verification =====
const vertices = Number(p.boundaryVertices || 0);
const TOLERANCE = Number(getEnv('BOUNDARY_TOLERANCE_PCT', 5));
let boundaryScore = vertices >= 4 ? 94 : vertices === 3 ? 80 : 40;
const overlapPct = vertices >= 4 ? 1.5 : vertices === 3 ? 4 : 12;
if (overlapPct > TOLERANCE) boundaryScore -= 20;
boundaryScore = clamp(boundaryScore);
const boundaryVerified = overlapPct <= TOLERANCE && boundaryScore >= 70;

// ===== Stage 8: Government registry cross-check =====
const registryConflicts = [];
if (!p.status) registryConflicts.push('missing_status');
let governmentScore = p.status === 'verified' ? 94 : 60;
governmentScore -= registryConflicts.length * 15;
governmentScore = clamp(governmentScore);
const governmentCleared = governmentScore >= 75 && registryConflicts.length === 0;
const registryCrossCheck = governmentCleared;

// ===== Stage 9: Community attestation check =====
const communityAttestations = Number(ex.communityAttestations != null ? ex.communityAttestations : (p.status === 'verified' ? 4 : 1));
const MIN_ATTESTATIONS = Number(getEnv('MIN_COMMUNITY_ATTESTATIONS', 3));
const activeObjection = ex.communityObjection === true;
let communityScore = clamp(60 + communityAttestations * 7);
const communityCleared = communityAttestations >= MIN_ATTESTATIONS && !activeObjection;

// ===== Stage 10: Risk analysis =====
const titleRisk = governmentCleared ? 10 : 45;
const boundaryRisk = 100 - boundaryScore;
const fraudRisk = fraudScore;
const environmentalRisk = 10;
const marketRisk = 20;
const ownershipRisk = fraudSignals.some(s => s.type === 'owner_identity_mismatch') ? 60 : 10;
const docCompletenessRisk = 100 - ocrConfidence;
const riskScore = clamp(
  titleRisk * 0.20 + boundaryRisk * 0.15 + fraudRisk * 0.25 + environmentalRisk * 0.05 +
  marketRisk * 0.10 + ownershipRisk * 0.15 + docCompletenessRisk * 0.10
);
const riskBand = riskScore >= 70 ? 'critical' : riskScore >= 45 ? 'high' : riskScore >= 25 ? 'moderate' : 'low';

// ===== Stage 11: Property valuation (INR only) =====
const rate = Number(getEnv('INR_CONVERSION_RATE', 100));
const base = Number(ex.valuation || (p.area ? p.area * 500 : 0));
const valuation = Math.round(base * rate);
const confidenceInterval = { low: Math.round(valuation * 0.92), high: Math.round(valuation * 1.08) };
const comparableProperties = [
  { ref: 'comp-1', valuation: Math.round(valuation * 0.97) },
  { ref: 'comp-2', valuation: Math.round(valuation * 1.04) },
];
const valuationFactors = ['area', 'region', 'property_type', 'registry_status', 'market_trend'];

// ===== Stage 12: Confidence scoring =====
const confidenceScore = clamp(
  ocrConfidence * 0.18 + boundaryScore * 0.15 + governmentScore * 0.17 + communityScore * 0.12 +
  (100 - fraudScore) * 0.15 + (100 - riskScore) * 0.13 + Number(ex.aiConfidence || 90) * 0.10
);

return [{ json: { ...d,
  ocr: { extracted, missingFields, anomalies, ocrConfidence, documentsVerified },
  fraud: { fraudScore, fraudBand, fraudSignals, criticalFraudSignal, recommendedAction: fraudRecommendedAction },
  boundary: { boundaryScore, overlapPct, boundaryVerified, tolerance: TOLERANCE },
  government: { governmentScore, governmentCleared, registryCrossCheck, conflicts: registryConflicts },
  community: { communityScore, communityAttestations, communityCleared, activeObjection },
  risk: { riskScore, riskBand, components: { titleRisk, boundaryRisk, fraudRisk, environmentalRisk, marketRisk, ownershipRisk, docCompletenessRisk } },
  valuationData: { currency: 'INR', valuation, confidenceInterval, comparableProperties, valuationFactors },
  confidenceScore,
} }];

const d = $input.first().json;
const ocr = d.ocr, fr = d.fraud, b = d.boundary, g = d.government, c = d.community, r = d.risk;
const activeDispute = (d.existingScores && d.existingScores.activeDispute === true) || false;
const reviewReasons = [];

const gates = {
  confidence: d.confidenceScore >= 78,
  fraudScore: fr.fraudScore < 25,
  fraudBand: fr.fraudBand === 'Clear',
  boundaryVerified: b.boundaryVerified === true,
  documentsVerified: ocr.documentsVerified === true,
  registryCrossCheck: g.registryCrossCheck === true,
  governmentCleared: g.governmentCleared === true,
  communityCleared: c.communityCleared === true,
  risk: r.riskScore < 45,
  noDispute: !activeDispute,
  noCriticalFraud: !fr.criticalFraudSignal,
};
if (!gates.confidence) reviewReasons.push('Confidence score below 78 (' + d.confidenceScore + ')');
if (!gates.fraudScore || !gates.fraudBand) reviewReasons.push('Fraud risk elevated (' + fr.fraudBand + ', score ' + fr.fraudScore + ')');
if (!gates.boundaryVerified) reviewReasons.push('Boundary not within tolerance');
if (!gates.documentsVerified) reviewReasons.push('Documents failed verification: ' + (ocr.missingFields.join(', ') || 'anomalies detected'));
if (!gates.registryCrossCheck || !gates.governmentCleared) reviewReasons.push('Government registry not cleared');
if (!gates.communityCleared) reviewReasons.push('Community verification incomplete or active objection');
if (!gates.risk) reviewReasons.push('Risk score too high (' + r.riskScore + ')');
if (!gates.noDispute) reviewReasons.push('Active dispute on property');

const allPass = Object.values(gates).every(Boolean);
const forgedDocs = fr.fraudSignals.some(s => s.type === 'forged_stamp');
const identityAbuse = fr.fraudSignals.some(s => s.type === 'owner_identity_mismatch');
const mustReject = fr.fraudBand === 'Critical' || fr.criticalFraudSignal || forgedDocs || identityAbuse;

let status, passportStatus, decisionReason;
if (allPass) {
  status = 'verified'; passportStatus = 'ready';
  decisionReason = 'All verification gates passed. Property Passport is ready.';
} else if (mustReject) {
  status = 'rejected'; passportStatus = 'held';
  decisionReason = 'Rejected due to critical fraud, forged documents, or identity abuse.';
  if (forgedDocs) reviewReasons.push('Forged document/stamp detected');
  if (identityAbuse) reviewReasons.push('Owner identity mismatch confirmed');
} else {
  status = 'manual_review'; passportStatus = 'held';
  decisionReason = 'One or more gates require human review.';
}

return [{ json: { ...d, decision: { status, passportStatus, decisionReason, reviewReasons, allPass, mustReject } } }];
